import { watchDom } from '../core/observer';
import { wasApplied, markApplied } from '../utils/dom';

const HERO_ID = 'ptv-home-hero';

function getBestCard() {
    return document.querySelector(
        '.homePage .card[data-type="Movie"], .homePage .card, .homePage .virtualScrollItem'
    );
}

function getCardImage(card) {
    if (!card) return '';

    const img =
        card.querySelector('img')
        || card.querySelector('.cardImage');

    if (!img) return '';

    return (
        img.currentSrc
        || img.src
        || img.getAttribute('src')
        || ''
    );
}

function getCardTitle(card) {
    return (
        card?.querySelector('.cardText')?.textContent?.trim()
        || card?.querySelector('.cardScalableText')?.textContent?.trim()
        || card?.getAttribute('data-name')
        || 'Featured'
    );
}

function buildHero() {
    const home = document.querySelector('.homePage');
    if (!home) return;

    let hero = document.getElementById(HERO_ID);

    if (!hero) {
        hero = document.createElement('section');
        hero.id = HERO_ID;
        hero.className = 'ptv-home-hero';

        home.prepend(hero);
    }

    const featured = getBestCard();
    if (!featured) return;

    const image = getCardImage(featured);
    const title = getCardTitle(featured);

    if (wasApplied(featured, 'ptvHeroSource')) return;

    markApplied(featured, 'ptvHeroSource');

    hero.innerHTML = `
        <div class="ptv-hero-backdrop"></div>

        <div class="ptv-hero-content">
            <div class="ptv-hero-kicker">FEATURED</div>

            <h1 class="ptv-hero-title">
                ${title}
            </h1>

            <div class="ptv-hero-buttons">
                <button class="ptv-hero-button ptv-hero-play">
                    <img src="/assets/icons/play.svg" alt="">
                    <span>Play</span>
                </button>

                <button class="ptv-hero-button ptv-hero-info">
                    <span>More Info</span>
                </button>
            </div>
        </div>
    `;

    const backdrop = hero.querySelector('.ptv-hero-backdrop');

    if (backdrop && image) {
        backdrop.style.backgroundImage = `url("${image}")`;
    }
}

watchDom(buildHero);
buildHero();
